#pragma once
#include "person_method_model.hpp"
#include <QSqlDatabase>
#include <QSqlQuery>
#include <QVariant>
#include <QDir>
#include <QFileInfo>
#include <QUuid>
class PersonMethodStore {
 QString path;
 struct Connection{QString name=QUuid::createUuid().toString();QSqlDatabase db=QSqlDatabase::addDatabase("QSQLITE",name);explicit Connection(QString p,bool readonly=false){db.setDatabaseName(p);db.setConnectOptions(readonly?"QSQLITE_OPEN_READONLY;QSQLITE_BUSY_TIMEOUT=100":"QSQLITE_BUSY_TIMEOUT=5000");if(!db.open()){db={};QSqlDatabase::removeDatabase(name);personMethod::need(false,"人物方法库打开失败");}if(readonly){QSqlQuery q(db);bool valid=q.exec("PRAGMA application_id")&&q.next()&&q.value(0).toInt()==1347235889;valid=valid&&q.exec("PRAGMA user_version")&&q.next()&&q.value(0).toInt()==1;if(!valid){q=QSqlQuery();db.close();db={};QSqlDatabase::removeDatabase(name);personMethod::need(false,"不是受支持的独立人物方法库，未改旧库");}}}~Connection(){db.close();db={};QSqlDatabase::removeDatabase(name);}};
 static QJsonObject parse(const QString& payload){QJsonParseError e;auto d=QJsonDocument::fromJson(payload.toUtf8(),&e);personMethod::need(e.error==QJsonParseError::NoError&&d.isObject(),"人物方法记录损坏，未清空");return personMethod::validate(d.object());}
 static QJsonArray rows(QSqlDatabase& db,QString kind){QSqlQuery q(db);q.prepare("SELECT payload FROM pm_records WHERE kind=? ORDER BY rowid");q.addBindValue(kind);personMethod::need(q.exec(),"人物方法读取失败");QJsonArray out;while(q.next())out.append(parse(q.value(0).toString()));return out;}
 static QJsonObject backup(QSqlDatabase& db){auto out=personMethod::empty();for(auto k:{"subjects","sources","methods"})out[k]=rows(db,k);return out;}
 static QJsonObject latest(QSqlDatabase& db,QString kind,QString entity){QSqlQuery q(db);q.prepare("SELECT payload FROM pm_records WHERE kind=? AND entity_id=? ORDER BY rowid DESC LIMIT 1");q.addBindValue(kind);q.addBindValue(entity);personMethod::need(q.exec(),"人物方法版本读取失败");return q.next()?parse(q.value(0).toString()):QJsonObject{};}
 static void insert(QSqlDatabase& db,const QJsonObject& r){personMethod::validate(r);QSqlQuery q(db);q.prepare("INSERT INTO pm_records(kind,id,entity_id,payload) VALUES(?,?,?,?)");q.addBindValue(r["kind"].toString());q.addBindValue(r["id"].toString());q.addBindValue(r["entityId"].toString());q.addBindValue(QString::fromUtf8(personMethod::json(r)));personMethod::need(q.exec(),"版本ID已存在或写入失败，未覆盖");}
public:
 explicit PersonMethodStore(QString file,bool initialize=true):path(QFileInfo(file).absoluteFilePath()){if(!initialize)return;QDir().mkpath(QFileInfo(path).absolutePath());Connection c(path);QSqlQuery q(c.db);personMethod::need(q.exec("PRAGMA application_id")&&q.next(),"库身份读取失败");int app=q.value(0).toInt();personMethod::need(q.exec("PRAGMA user_version")&&q.next(),"库版本读取失败");int version=q.value(0).toInt();if(app==0&&version==0){personMethod::need(q.exec("SELECT count(*) FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%' AND name!='android_metadata'")&&q.next()&&q.value(0).toInt()==0,"不是空独立人物方法库，未重建");personMethod::need(c.db.transaction(),"建库事务失败");try{personMethod::need(q.exec("CREATE TABLE pm_records(kind TEXT NOT NULL,id TEXT NOT NULL,entity_id TEXT NOT NULL,payload TEXT NOT NULL,PRIMARY KEY(kind,id))")&&q.exec("PRAGMA application_id=1347235889")&&q.exec("PRAGMA user_version=1"),"建库失败");personMethod::need(c.db.commit(),"建库提交失败");}catch(...){c.db.rollback();throw;}}else personMethod::need(app==1347235889&&version==1,"不是受支持的独立人物方法库，未改旧库");personMethod::need(q.exec("SELECT kind,id,entity_id,payload FROM pm_records LIMIT 0"),"库结构不兼容，未重建");}
 QString filePath()const{return path;}
 QJsonObject backup()const{if(!QFileInfo::exists(path))return personMethod::empty();Connection c(path,true);personMethod::need(c.db.transaction(),"读取快照失败");try{auto out=backup(c.db);personMethod::need(c.db.commit(),"读取快照提交失败");return out;}catch(...){c.db.rollback();throw;}}
 QJsonObject latest(QString kind,QString entity)const{if(!QFileInfo::exists(path))return {};Connection c(path,true);return latest(c.db,kind,entity);}
 QJsonObject get(QString kind,QString id)const{if(!QFileInfo::exists(path))return {};Connection c(path,true);QSqlQuery q(c.db);q.prepare("SELECT payload FROM pm_records WHERE kind=? AND id=?");q.addBindValue(kind);q.addBindValue(id);personMethod::need(q.exec(),"版本读取失败");return q.next()?parse(q.value(0).toString()):QJsonObject{};}
 QJsonObject append(QJsonObject r,const QJsonObject& expected){r=personMethod::seal(r);PersonMethodStore validated(path);Connection c(path);personMethod::need(c.db.transaction(),"保存事务失败");try{auto current=latest(c.db,r.value("kind").toString(),r.value("entityId").toString());personMethod::need(personMethod::canonical(current)==personMethod::canonical(expected),"对象或方法最新版本已变化，草稿未覆盖，请显式重读或放弃");personMethod::need(r.value("parentId").toString()==current.value("id").toString(),"父版本不匹配");insert(c.db,r);personMethod::need(c.db.commit(),"版本提交失败");return r;}catch(...){c.db.rollback();throw;}}
 void merge(const QJsonObject& incoming,const QJsonObject& expected){auto input=personMethod::decode(personMethod::json(incoming));PersonMethodStore validated(path);Connection c(path);personMethod::need(c.db.transaction(),"导入事务失败");try{auto current=backup(c.db);personMethod::need(personMethod::canonical(current)==personMethod::canonical(expected),"人物方法库已变化，请重新预览，未写入");auto inserts=personMethod::preview(input,current)["inserts"].toObject();for(auto k:{"subjects","sources","methods"})for(auto v:inserts[k].toArray())insert(c.db,v.toObject());personMethod::need(c.db.commit(),"导入提交失败");}catch(...){c.db.rollback();throw;}}
};
